mapper.update:
UPDATE chat_session
SET message_count = message_count + 1
WHERE id = #{sessionId}

mapper.select:
SELECT id, agent_id, user_id, title, message_count, created_at, updated_at
FROM chat_session
WHERE user_id = #{userId}
  AND agent_id = #{agentId}
ORDER BY updated_at DESC
LIMIT #{limit}
